class Solution:
    def findNumberOfLIS(self, nums: list[int]) -> int:
        best = count = 0
        n = len(nums)
        def dfs(i: int, prev: int, length: int) -> None:
            nonlocal best, count
            if i == n:
                if length > best:
                    best, count = length, 1
                elif length == best:
                    count += 1
                return
            dfs(i + 1, prev, length)
            if prev == -1 or nums[i] > nums[prev]:
                dfs(i + 1, i, length + 1)
        dfs(0, -1, 0)
        return count

solutions.better:
class Solution:
    def findNumberOfLIS(self, nums: list[int]) -> int:
        from functools import lru_cache
        n = len(nums)
        @lru_cache(None)
        def dp(i: int, prev: int) -> tuple[int, int]:
            if i == n:
                return (0, 1)
            best_len, ways = dp(i + 1, prev)
            if prev == -1 or nums[i] > nums[prev]:
                take_len, take_ways = dp(i + 1, i)
                take_len += 1
                if take_len > best_len:
                    best_len, ways = take_len, take_ways
                elif take_len == best_len:
                    ways += take_ways
            return (best_len, ways)
        return dp(0, -1)[1]

